import {communityAdmin,communityPreview} from './community-client.mjs?v=recovery1';
import {currentUser,supabase} from './auth-client.mjs';
import {communityLabel} from './community-model.mjs';
import {recoveryKey,recoveryRecord,validRecovery} from './community-recovery-model.mjs';
import {confirmDialog} from './site-dialogs.mjs?v=1';
const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
export function installCommunityRecovery({panel,getState,recover,restored,run,message,onScopeChange}){
 let scope=null,timer=null,historySerial=0;
 const editor=panel.querySelector('.community-editor'),box=el('section'),history=el('details'),summary=el('summary','Version history & restore'),versions=el('div');box.className='community-recovery';box.setAttribute('aria-label','Draft recovery');history.className='community-history';history.append(summary,versions);editor.prepend(box);editor.append(history);
 function records(){if(!scope)return [];const result=[];try{const prefix='community-draft-recovery-v1:'+scope+':';for(const key of Object.keys(localStorage)){if(!key.startsWith(prefix))continue;let value;try{value=JSON.parse(localStorage.getItem(key));}catch{continue;}if(validRecovery(value,scope))result.push(value);else localStorage.removeItem(key);}}catch{message('Browser recovery is unavailable. Use Save draft before leaving.');}return result;}
 function capture(){clearTimeout(timer);const state=getState();if(!scope||!state.dirty)return;try{const value=recoveryRecord(scope,state);localStorage.setItem(recoveryKey(scope,state.kind,state.active?.id),JSON.stringify(value));if(box.hidden){box.hidden=false;box.replaceChildren(el('strong','Draft recovery'));const text=el('p');text.dataset.saveStatus='';box.append(text);}const text=box.querySelector('[data-save-status]');if(text)text.textContent='Recovery copy saved in this browser. Use Save draft to save to the dashboard.';}catch{message('Could not save a browser recovery copy. Use Save draft before leaving.');}}
 function schedule(){clearTimeout(timer);timer=setTimeout(capture,400);}
 function clear(kind,id){if(!scope)return;try{localStorage.removeItem(recoveryKey(scope,kind,id));}catch{}}
 function offer(){historySerial++;versions.replaceChildren();history.open=false;history.hidden=!getState().active;box.replaceChildren();const state=getState(),items=records().filter(r=>r.kind===state.kind);box.hidden=!items.length&&!state.dirty;if(box.hidden)return;box.append(el('strong','Draft recovery'));const saved=el('p','Unfinished edits are kept in this browser for 7 days. They are not published.');saved.dataset.saveStatus='';box.append(saved);for(const item of items){const row=el('div'),name=el('span',communityLabel(item.kind,item.values)+' · '+new Date(item.at).toLocaleString()),restore=el('button','Recover unsaved draft'),discard=el('button','Discard recovery');restore.type=discard.type='button';restore.onclick=async()=>{if(!await confirmDialog('Recover these unsaved edits? A newer saved version may exist: review the recovered edits before saving. Published content will stay unchanged.'))return;capture();recover(item);message('Recovered unsaved edits. Review and Save draft when ready.');};discard.onclick=async()=>{if(!await confirmDialog('Discard this browser recovery copy?'))return;clear(item.kind,item.id);offer();};row.append(name,restore,discard);box.append(row);}}
 async function configure(){const next=communityPreview?'preview':(await currentUser())?.id||null;if(next!==scope){if(scope)capture();onScopeChange();scope=next;clearTimeout(timer);}offer();}
 panel.addEventListener('input',schedule);panel.addEventListener('click',()=>{if(getState().dirty)schedule();});window.addEventListener('pagehide',capture);window.addEventListener('beforeunload',event=>{if(getState().dirty){capture();event.preventDefault();event.returnValue='';}});
 document.addEventListener('click',async event=>{const target=event.target.closest('a,[data-panel]');if(!getState().dirty||!target||target.dataset.communityKind||target.dataset.recoveryNavigation==='true'||(target.tagName==='A'&&target.target==='_blank'))return;event.preventDefault();event.stopImmediatePropagation();capture();if(!await confirmDialog('Leave these unsaved edits? A recovery copy stays in this browser.'))return;target.dataset.recoveryNavigation='true';target.click();delete target.dataset.recoveryNavigation;},true);
 if(!communityPreview)supabase.auth.onAuthStateChange((_event,session)=>{if(scope&&scope!==session?.user?.id){capture();scope=null;onScopeChange();box.replaceChildren();history.hidden=true;}});
 history.addEventListener('toggle',async()=>{if(!history.open)return;const active=getState().active,serial=++historySerial;if(!active)return;versions.replaceChildren(el('p','Loading versions…'));try{const list=await communityAdmin('history',{id:active.id});if(serial!==historySerial||getState().active?.id!==active.id)return;versions.replaceChildren();if(!list.length)versions.append(el('p','No saved versions yet.'));for(const version of list){const details=el('details'),caption=el('summary','Revision '+version.snapshot.revision+' · '+version.action+' · '+new Date(version.created_at).toLocaleString()),text=el('pre'),button=el('button','Restore to draft');text.textContent=Object.entries(version.snapshot.draft).map(([key,value])=>key.replaceAll('_',' ')+': '+(Array.isArray(value)?value.map(v=>v.title||'').join('; '):String(value))).join('\n');button.type='button';button.onclick=async()=>{if(!await confirmDialog('Restore this version to the draft? Current draft edits will be replaced. Published content will stay unchanged.'))return;capture();run(async()=>{const state=getState();const row=await communityAdmin('restore',{id:state.active.id,revision:state.active.revision,version:version.id});clear(state.kind,state.active.id);await restored(row);message('Version restored to draft. Review it before publishing.');});};details.append(caption,text,button);versions.append(details);}}catch(error){versions.replaceChildren(el('p',error.message));}});
 return {capture,clear,offer,configure};
}
